// Wait for the page to be fully loaded
document.addEventListener('DOMContentLoaded', function () {

  // Get all the necessary elements
  const container = document.getElementById('post-container');
  const sidebar = document.getElementById('post-sidebar');
  const tocContainer = document.getElementById('post-toc');
  const toggleButton = document.getElementById('sidebar-toggle');
  
  // Find the Table of Contents generated by Jekyll
  const generatedToc = document.getElementById('markdown-toc');

  console.log("Container:", container);             // Add this
  console.log("Sidebar:", sidebar);                 // Add this
  console.log("TOC Container:", tocContainer);     // Add this
  console.log("Toggle Button:", toggleButton);       // Add this
  console.log("Generated ToC in post:", generatedToc); // Add this


  // If a ToC and a sidebar exist, let's proceed
  if (generatedToc && tocContainer && container) {
    // Move the generated ToC into our sidebar
    tocContainer.appendChild(generatedToc);

    // Make the toggle button functional
    toggleButton.addEventListener('click', function() {
      container.classList.toggle('sidebar-collapsed');

      // Change arrow direction
      if (container.classList.contains('sidebar-collapsed')) {
        toggleButton.innerHTML = '&rarr;'; // Right arrow when collapsed
        toggleButton.title = 'Show Contents';
      } else {
        toggleButton.innerHTML = '&larr;'; // Left arrow when open
        toggleButton.title = 'Hide Contents';
      }
    });

  } else {
    // If there's no ToC on the page, hide the sidebar and the button
    if(sidebar) sidebar.style.display = 'none';
    if(toggleButton) toggleButton.style.display = 'none';
  }
});